// Secure version of the application
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { body, validationResult } = require('express-validator');
const app = express();

// Security Middleware
app.use(helmet());

// CORS Configuration - restrict to specific domains in production
app.use(cors({
  origin: ['https://yourdomain.com', 'http://localhost:3000'],
  methods: ['GET'],
  allowedHeaders: ['Content-Type']
}));

// Rate Limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});
app.use(limiter);

// Middleware to parse JSON bodies with size limit
app.use(express.json({ limit: '10kb' }));

// Security Headers
app.use((req, res, next) => {
  // Content Security Policy
  res.setHeader(
    "Content-Security-Policy",
    "default-src 'self'; connect-src 'self'; script-src 'self';"
  );

  // XSS Protection
  res.setHeader("X-XSS-Protection", "1; mode=block");

  // Prevent MIME sniffing
  res.setHeader("X-Content-Type-Options", "nosniff");

  // Clickjacking protection
  res.setHeader("X-Frame-Options", "DENY");
  next();
});

// Health endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      // Avoid exposing detailed server information
      uptime: process.uptime()
    });
  } catch (error) {
    // Generic error message, don't expose details
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Users endpoint with proper sanitization
app.get('/users', (req, res) => {
  try {
    // In a real application, this would come from a database
    // with proper authorization checks
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' }
    ];

    // Sanitize response data
    const sanitizedUsers = users.map(user => ({
      id: user.id,
      name: sanitizeOutput(user.name),
      email: sanitizeOutput(user.email)
    }));

    res.json(sanitizedUsers);
  } catch (error) {
    // Log detailed error but return generic message
    console.error('Users endpoint error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Utility function to sanitize output (basic example)
function sanitizeOutput(text) {
  // In a real app, use a library like DOMPurify or xss
  return text.replace(/</g, "&").replace(/>/g, ">").replace(/"/g, "&quot;");
}

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  // Don't expose detailed error information
  res.status(500).json({ error: 'Internal server error' });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// Start server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

module.exports = app;

